Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Section FT.
  Variables (ra sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x24 x25 x26 x27 : word).               (* [comment removed for export] *)
  Variables (m0 : fmem) (S TB DST dcap tl : Z) (bs : list Z) (dt : dtable).
  Variables (wb wp : word) (jp : list byte).         (* [comment removed for export] *)
  Variable POST : machine_state -> Prop.
  Notation SP := (bv_unsigned sp).
  Hypothesis HTL : 1 <= tl <= 12.
  Hypothesis HCELLS : zlen (dt_cells dt) = 2^tl.
  Hypothesis HCOK : cells_ok tl (dt_cells dt).
  Hypothesis TBB : bytes_at psegs m0 TB (concat (map fse_cell_bytes (dt_cells dt))).
  Hypothesis SRC : bytes_at psegs m0 S (map (Z_to_bv 8) bs).
  Hypothesis BY : Forall (fun c => 0 <= c < 256) bs.
  Hypothesis HS : 8 <= S /\ S + Z.max 8 (zlen bs) + 8 <= 2^64.
  Hypothesis HTB : 0 < TB /\ TB + 4 * 2^tl <= 2^64.
  Hypothesis HDST : 3 <= DST /\ DST + dcap < 2^64 /\ 0 <= dcap <= 255.
  Hypothesis HSP : SP + 88 <= 2^64.
  Hypothesis DJ1 : DST + dcap <= TB \/ TB + 4 * 2^tl <= DST.
  Hypothesis DJ2 : DST + dcap <= S \/ S + zlen bs <= DST.
  Hypothesis DJF : DST + dcap <= SP + 48 /\ TB + 4 * 2^tl <= SP + 48 /\ S + zlen bs <= SP + 48.

  Notation WFT := [(SP + 48, SP + 88); (DST, DST + dcap)].
  Notation FBC w := [C8 w; C4 wb; CB 4 jp; C8 wp; C8 (Z_to_bv 64 S); C8 (Z_to_bv 64 (S + 8))].

  Definition ft_inv (m1 : fmem) (out : list Z) : Prop :=
    (exists junk, u8arr psegs m1 DST (map (Z_to_bv 8) out ++ junk) /\ zlen junk = dcap - zlen out)
    /\ (exists w, rw_cells psegs m1 (SP + 48) (FBC w))
    /\ munch WFT m0 m1 /\ wmono psegs m0 m1 /\ mem_inv psegs m1.

  Notation TH pc mm x5 x6 x7 x8 x9 x11 x13 x17 x18 x21 x22 x23 x29 x30 x31 :=
    (MS (mkR ra sp gp tp x5 x6 x7 x8 x9 (Z_to_bv 64 (S + 8)) x11 (Z_to_bv 64 S) x13 (Z_to_bv 64 (-70)) (Z_to_bv 64 TB)
             (Z_to_bv 64 TB) x17 x18 (Z_to_bv 64 DST) (Z_to_bv 64 (DST + dcap - 2)) x21 x22 x23 x24 x25 x26 x27
             (Z_to_bv 64 64) x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).
  Notation TX mm a4v y5 y6 y7 y8 y9 y10 y11 y12 y13 y15 y16 y17 y18 y19 y20 y21 y22 y23 y28 y29 y30 y31 :=
    (MS (mkR ra sp gp tp y5 y6 y7 y8 y9 y10 y11 y12 y13 (Z_to_bv 64 a4v) y15 y16 y17 y18 y19 y20 y21 y22 y23 x24 x25 x26 x27
             y28 y29 y30 y31)
        F (Z_to_bv 64 0x1be74) fc None mm (seg_rom psegs)).

  Definition ft_fin (r : res (list Z)) (m2 : fmem) (a4v : Z) : Prop :=
    munch WFT m0 m2 /\ wmono psegs m0 m2 /\ mem_inv psegs m2 /\
    match r with
    | Ok l => a4v = zlen l /\ exists junk, u8arr psegs m2 DST (map (Z_to_bv 8) l ++ junk) /\ zlen junk = dcap - zlen l
    | Err e => a4v = - e /\ 0 < e < 120
    | Ub | NoFuel => False
    end.

  Definition ft_K (r : res (list Z)) : Prop :=
    forall m2 a4v (y5 y6 y7 y8 y9 y10 y11 y12 y13 y15 y16 y17 y18 y19 y20 y21 y22 y23 y28 y29 y30 y31 : word),
      ft_fin r m2 a4v -> evt psegs POST (TX m2 a4v y5 y6 y7 y8 y9 y10 y11 y12 y13 y15 y16 y17 y18 y19 y20 y21 y22 y23 y28 y29 y30 y31).

  Ltac osb OUTA LJ :=
    let SOK := fresh "SOK" in
    lazymatch type of OUTA with u8arr _ ?mm ?D (map (Z_to_bv 8) ?o ++ ?j) =>
    pose proof (u8arr_store_ok psegs mm D _ (zlen o) (wa (D + zlen o)) OUTA
                  ltac:(repeat (rewrite length_app || rewrite length_map); cbn [length]; lia) eq_refl) as SOK;
    zstep;
    lazymatch goal with
    | |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ (wa ?E) _) _) =>
        replace E with (D + zlen o) by (rewrite ?length_app; cbn [length]; lia)
    | |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ (Z_to_bv 64 ?E) _) _) =>
        replace E with (D + zlen o) by (rewrite ?length_app; cbn [length]; lia)
    end;
    rewrite le1_lit;
    lazymatch goal with |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ _ [Z_to_bv 8 ?v]) _) =>
      let OUT2 := fresh "OUTA" in
      let LJ2 := fresh "LJ" in
      pose proof (out_sb psegs mm D o j v OUTA ltac:(lia)) as OUT2;
      let LO2 := fresh "LO" in
      assert (LO2 : zlen (o ++ [v]) = zlen o + 1) by (rewrite length_app; cbn [length]; lia);
      assert (LJ2 : zlen (List.tl j) = dcap - zlen (o ++ [v])) by (rewrite zlen_tl by lia; lia);
      clear OUTA LJ; store_done; rename OUT2 into OUTA; rename LJ2 into LJ
    end end.

  Lemma tbb_at : forall m1, munch WFT m0 m1 -> bytes_at psegs m1 TB (concat (map fse_cell_bytes (dt_cells dt))).
