  Lemma ft_c2 : forall out2 c b nb2 ns2 m1 (x5 x9 x11 x13 x17 x18 x21 x22 x23 x31 : word),
    0 <= b <= 2^30 -> 0 <= c < 2^64 -> 0 <= nb2 <= 12 -> 0 <= ns2 < 65536 ->
    ft_inv m1 out2 -> 1 <= zlen out2 <= dcap ->
    (dcap - 2 < zlen out2 -> ft_K (Err ZSTD_error_dstSize_tooSmall)) ->
    (zlen out2 <= dcap - 2 -> forall (z29 z30 z31 : word),
       evt psegs POST (TH 0x1c91c m1 x5 (Z_to_bv 64 (ns2 + lbf c b nb2)) (Z_to_bv 64 (DST + zlen out2 + 1))
                          (Z_to_bv 64 nb2) x9 x11 x13 x17 x18 x21 x22 x23 z29 z30 z31)) ->
    evt psegs POST (TH 0x1c900 m1 x5 (Z_to_bv 64 ns2) (Z_to_bv 64 (DST + zlen out2 - 1)) (Z_to_bv 64 nb2) x9 x11 x13 x17 x18
                       x21 x22 x23 (Z_to_bv 64 b) (Z_to_bv 64 c) x31).
Proof.
