  Notation HEADT x mm x8 x9 x18 x21 x22 x23 x29 x30 x31 :=
    (TH 0x1c91c mm (Z_to_bv 64 (de_s1 x)) (Z_to_bv 64 (de_s2 x)) (Z_to_bv 64 (DST + zlen (de_out x) + 1)) x8 x9
        (Z_to_bv 64 (bd_reg S (de_bd x))) (Z_to_bv 64 (bd_bits (de_bd x))) (Z_to_bv 64 (bd_cont (de_bd x))) x18 x21 x22 x23
        x29 x30 x31).

  Definition ft_loop_stmt (f : nat) : Prop :=
    forall x r m1 (x8 x9 x18 x21 x22 x23 x29 x30 x31 : word),
      tail_loop bs dt dcap true f x = r -> res_ok r -> bitd_ok bs (de_bd x) -> bd_bits (de_bd x) <= 2^29 ->
      zlen (de_out x) <= dcap - 2 -> ft_inv m1 (de_out x) -> ft_K r ->
      evt psegs POST (HEADT x m1 x8 x9 x18 x21 x22 x23 x29 x30 x31).

  (* [comment removed for export] *)
  Lemma ft_h2 : forall f out1 s1a s2 d1r r m1 (b0 ns1 nb1 c0 : Z) (x8 x9 x18 x21 x22 x23 : word),
    ft_loop_stmt f ->
    ftl_body2 f out1 s1a s2 d1r = r -> res_ok r ->
    bitd_ok bs d1r -> bd_bits d1r <= 64 -> bd_zero d1r = false ->
    zlen out1 <= dcap - 2 ->
    s1a = ns1 + lbf c0 b0 nb1 ->
    0 <= b0 <= 2^30 -> 0 <= c0 < 2^64 -> 0 <= nb1 <= 12 -> 0 <= ns1 < 65536 ->
    ft_inv m1 out1 -> ft_K r ->
    evt psegs POST (TH 0x1c9d4 m1 (Z_to_bv 64 ns1) (Z_to_bv 64 s2) (Z_to_bv 64 (DST + zlen out1)) x8 x9
                       (Z_to_bv 64 (S + bd_ptr d1r)) (Z_to_bv 64 b0) (Z_to_bv 64 c0) x18 x21 x22 x23
                       (Z_to_bv 64 (bd_bits d1r)) (Z_to_bv 64 (bd_cont d1r)) (Z_to_bv 64 nb1)).
